const services={ai:{kicker:'BUILT AROUND YOUR BUSINESS',title:'AI with a purpose.\nSoftware with an edge.',description:'Move beyond the AI conversation. Build useful AI applications, knowledge assistants, and intelligent experiences that fit the way your business works.',tags:['Generative AI','AI assistants','Custom integrations']},consulting:{kicker:'A CLEARER PATH TO WHAT’S NEXT',title:'Better decisions.\nA stronger direction.',description:'Make technology decisions with confidence. Align your AI opportunities, software architecture, and digital roadmap with your business priorities.',tags:['AI readiness','Technology strategy','Solution architecture']},software:{kicker:'FROM IDEA TO EVERYDAY ESSENTIAL',title:'Thoughtfully designed.\nEngineered to evolve.',description:'Turn a promising idea into a useful digital product. Bring design, web development, and dependable engineering together around your users.',tags:['Web applications','Digital platforms','Product development']},automation:{kicker:'MAKE ROOM FOR HIGHER-VALUE WORK',title:'Smarter workflows.\nMore human potential.',description:'Connect your systems and simplify repetitive processes. Build practical automations that help your team spend more time on work that matters.',tags:['Workflow automation','System integrations','AI-powered processes']}};
const tabs=[...document.querySelectorAll('[role="tab"]')];
function selectService(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});const s=services[tab.dataset.service];document.getElementById('service-kicker').textContent=s.kicker;const title=document.getElementById('service-title');title.replaceChildren(...s.title.split('\n').flatMap((part,i)=>i?[document.createElement('br'),document.createTextNode(part)]:[document.createTextNode(part)]));document.getElementById('service-description').textContent=s.description;document.getElementById('service-tags').replaceChildren(...s.tags.map(text=>{const span=document.createElement('span');span.textContent=text;return span}));document.getElementById('service-panel').setAttribute('aria-labelledby',tab.id)}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectService(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectService(tabs[next]);tabs[next].focus()}})});
const menu=document.querySelector('.menu');const nav=document.getElementById('navigation');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')};menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu()}});
document.getElementById('year').textContent=new Date().getFullYear();
document.getElementById('contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const subject=`Project enquiry: ${data.get('service')}`;const body=`Hello Nexvorx,\n\n${data.get('message')}\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nInterested in: ${data.get('service')}`;window.location.href=`mailto:nexvorx@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;document.getElementById('form-status').textContent='Your email draft is ready in your email app. Please send it there to contact Nexvorx. If no app opened, email nexvorx@gmail.com directly.'});
